<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuthSessionStore} from '../../stores/authSession'
import {moduleRequest,ModuleApiError} from './api'
import {useCatalogText} from './text'
import {displayName} from '../shared-commerce/format'
import type {Category,Product} from './types'
import type {ProductDetail} from './editor/useCatalogProductEditor'
import CatalogProductList from './CatalogProductList.vue'
import CatalogCategories from './CatalogCategories.vue'
import CatalogAvailability from './CatalogAvailability.vue'
import CatalogProductEditor from './editor/CatalogProductEditor.vue'
import '../shared-commerce/commerce.css'
const {t,locale}=useCatalogText(),route=useRoute(),auth=useAuthSessionStore(),store=computed(()=>String(route.params.storeId)),base=computed(()=>`/api/v1/stores/${store.value}/catalog`)
const products=ref<Product[]>([]),categories=ref<Category[]>([]),view=ref<'products'|'categories'|'availability'|'editor'>('products'),editingId=ref<string|null>(null),loading=ref(false),childBusy=ref(false),error=ref(''),choice=ref<{product:Product;action:string}|null>(null),pending=ref<{path:string;body:Record<string,unknown>}|null>(null)
const globalCatalog=computed(()=>auth.user?.roles.includes('tenant_admin')===true),can=(p:string)=>auth.user?.permissions.includes(p)===true,blocked=computed(()=>loading.value||childBusy.value||!!pending.value)
let generation=0
async function load(){const own=generation;loading.value=true;error.value='';try{const[c,p]=await Promise.all([moduleRequest<Category[]>(base.value,'/categories'),moduleRequest<Product[]>(base.value,'/products')]);if(own===generation){categories.value=c;products.value=p}}catch(e){if(own===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(own===generation)loading.value=false}}
function edit(p?:Product){editingId.value=p?.id??null;view.value='editor';error.value=''}
function saved(value:ProductDetail){editingId.value=value.product.id;const i=products.value.findIndex(p=>p.id===value.product.id);if(i<0)products.value.unshift(value.product);else products.value[i]=value.product}
async function apply(){if(!choice.value||loading.value)return;const own=generation,{product:p,action}=choice.value;pending.value??={path:`/products/${p.id}/${action==='listing'?'listing':'status'}`,body:action==='listing'?{priceCents:p.priceCents,channels:p.channels,enabled:!p.listingEnabled,expectedVersion:p.listingVersion,idempotencyKey:crypto.randomUUID()}:{status:action,expectedVersion:p.version,idempotencyKey:crypto.randomUUID()}};loading.value=true;error.value='';try{const result=await moduleRequest<Product>(base.value,pending.value.path,'POST',pending.value.body);if(own===generation){pending.value=null;choice.value=null;saved({product:result,barcodes:[]})}}catch(e){if(own===generation){error.value=e instanceof Error?e.message:String(e);if(e instanceof ModuleApiError&&e.status<500)pending.value=null}}finally{if(own===generation)loading.value=false}}
watch(store,()=>{generation++;view.value='products';products.value=[];categories.value=[];childBusy.value=false;pending.value=null;choice.value=null;void load()},{immediate:true})
</script>
<template><main class="cards-page catalog-page"><nav><RouterLink :to="`/stores/${store}/wallet/more`">← {{t('back')}}</RouterLink><h1>{{t('catalog')}}</h1><button v-if="view!=='editor'" :disabled="blocked" @click="load">{{t('refresh')}}</button></nav><p v-if="error" class="cards-error" role="alert">{{error}}</p><p v-if="loading" role="status">{{t('loading')}}</p><template v-if="view!=='editor'"><nav :aria-label="t('catalog')"><button v-for="item in ['products','categories','availability'] as const" :key="item" :class="{primary:view===item}" :aria-pressed="view===item" :disabled="blocked" @click="view=item;choice=null">{{t(item==='products'?'productList':item==='categories'?'categoryManage':'availabilityManage')}}</button></nav><section v-if="view==='products'"><div class="cards-actions"><h2>{{t('productList')}}</h2><button v-if="globalCatalog&&can('catalog.manage')" :disabled="blocked" @click="edit()">＋ {{t('newProduct')}}</button></div><CatalogProductList :products="products" :categories="categories" :can-edit="can('catalog.manage')" :disabled="blocked" @edit="edit"/></section><CatalogCategories v-if="view==='categories'" :key="base" :base="base" :categories="categories" :can-edit="globalCatalog&&can('catalog.manage')" @saved="load" @busy="childBusy=$event"/><CatalogAvailability v-if="view==='availability'" :products="products" :global-publish="globalCatalog&&can('catalog.publish')" :can-manage="can('catalog.manage')" :disabled="blocked" @change="(product,action)=>choice={product,action}"/><section v-if="choice" role="dialog" :aria-label="t('confirmChange')" class="cards-panel"><h3>{{t('confirmChange')}}</h3><p>{{displayName(choice.product,locale)}} · {{choice.product.code}}</p><p>{{t(choice.action==='listing'?(choice.product.listingEnabled?'storeOff':'storeOn'):choice.action)}}</p><button :disabled="loading" @click="apply">{{t(pending?'recover':'confirm')}}</button><button :disabled="blocked" @click="choice=null">{{t('cancel')}}</button></section></template><CatalogProductEditor v-else :key="base" :base="base" :product-id="editingId" :categories="categories" :global-edit="globalCatalog" @saved="saved" @busy="childBusy=$event" @cancel="view='products';childBusy=false"/></main></template>
